-- 让某个 panel 闪一下, debug 效果
---@return System.Collections.IEnumerator
---@param panel_    UnityEngine.UI.Image
---@param flashColor_   Color
---@param speed_    number
function QuestUtils.FlashPanel(panel_, flashColor_, speed_)
    speed_ = speed_ or 2.0
    --panel_.gameObject:SetActive(true)
    KTool.SetActive( panel_.gameObject, true )
    -- 先彻底点亮:
    local c = flashColor_
    c.a = 1.0
    panel_.color = c
    -- 慢慢熄灭
    while c.a > 0.01 do
        c.a = c.a - speed_ * Time.deltaTime
        c.a = math.max(c.a, 0.0)
        panel_.color = c
        coroutine.yield(Yielders.EndOfFrame)
    end
    c.a = 0
    panel_.color = c
    --panel_.gameObject:SetActive(false)
    KTool.SetActive( panel_.gameObject, false )
end





function QuestUtils.ReadTaskRangeFromLuaParameters( paramsComp_ )

    local lowestTaskID  = LuaParametersReader.Read( paramsComp_, "lowestTaskID", LuaParametersReader.Type.String )
    local highestTaskID = LuaParametersReader.Read( paramsComp_, "highestTaskID", LuaParametersReader.Type.String )
    assert( type(lowestTaskID) == "string" and (#lowestTaskID>0) )
    assert( type(highestTaskID) == "string" and (#highestTaskID>0) )

    return TaskRange.New( lowestTaskID, highestTaskID )
end





return QuestUtils

